import ctypes
from typing import List, Tuple, Any, Union

from .message_handling import (Structure, SMessageHeader,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32)
from .receiver_interface import ServiceElement

from ..commons import DSP_RESOURCES, LOGGER
from ..utils import get_context_id, get_procedure_id, intlify, memoize

from ..data_layer.sack_reflection_interface import (get_browser_object_name, get_message_name,
                                                    FOUR_BITS, CPU1, CPUA, SYSTEM_TYPE_KEPLER)


@register_message
class BrowserServicesReq(RequestMessage):
    id = 0x1e1d

    _fields_ = [
        ('header', SMessageHeader),
        ('requestedServices', u32),
        ('contextId', u32),
        ('procedureId', u32)
    ]

    def __init__(self, board, cpu, *args, **kwargs):
        super(BrowserServicesReq, self).__init__(board, cpu, *args, **kwargs)
        self.contextId = get_context_id()
        self.procedureId = get_procedure_id()


@register_message
class BrowserServicesResp(ResponseMessage):
    id = 0x1e1e

    _fields_ = [
        ('header', SMessageHeader),
        ('requestedServices', u32),
        ('status', u32),
        ('contextId', u32),
        ('procedureId', u32),
        ('numberOfItems', u32),
        ('itemSize', u32),
        ('dynamicData', u32 * 1)
    ]


class SBrowserServiceElement(Structure):
    _fields_ = [
        ('cpuAddress', u32),
        ('objectType', u32),
        ('messageId', u32),
        ('availableService', u32),
    ]


class BrowserServicesQuery(Query):
    def __init__(self, req, resp):
        super(BrowserServicesQuery, self).__init__(req, resp)

        self.service_element_data = []

    def _handle_response(self):

        number_of_items = self.resp_msg.numberOfItems

        offset = ctypes.sizeof(BrowserServicesResp) - ctypes.sizeof(u32)  # i.e., minus the size of dynamicData 'pointer' -> 40
        data_stream = self.resp_stream[offset:]

        element_size = ctypes.sizeof(SBrowserServiceElement)

        service_element_data = []
        for item in range(number_of_items):
            browser_service_element = SBrowserServiceElement.from_buffer(
                data_stream[item * element_size:(item + 1) * element_size]
            )
            service_element = ServiceElement()
            service_element.cpu = (browser_service_element.cpuAddress >> 16) & 0x000000FF
            service_element.board = browser_service_element.cpuAddress >> 24
            service_element.objectType = browser_service_element.objectType
            service_element.messageId = browser_service_element.messageId
            service_element.availableService = browser_service_element.availableService

            service_element_data.append(service_element)

        # self.service_element_data = service_element_data
        self.service_element_data = service_element_data


UNKNOWN_SERVICE = 65535


@memoize
def _get_services_for_chip_and_cache_results(board, chip, connection):
    # type: (int, int, ...) -> List[Tuple[int, int, int]]
    """
    As observed in Wireshark logs, BrowserServicesReq is always initialized with the first CPU on chip
    (0x31, 041, 0x51 etc.).
    On the other hand, BrowserServicesResp carries info about services available for the whole chip,
    e.g., for board=0x13, cpu=0x31, one gets services for
    board 0x13 cpu 0x31
    board 0x13 cpu 0x32
    board 0x13 cpu 0x33
    board 0x13 cpu 0x34

    An extra query is needed for FSMr4 CPU ARMs.
    """
    chip_ids = DSP_RESOURCES.get_chip_ids_for_board(board)
    if chip not in chip_ids:
        raise RuntimeError('Incorrect chip id: {}'.format(chip))

    services_for_chip = []
    first_cpu_on_chip = chip + CPU1
    query = BrowserServicesQuery(
        BrowserServicesReq(board, first_cpu_on_chip), BrowserServicesResp()
    )
    qm = BasicQueryManager(query, connection)
    qm.send_request_and_wait_for_response(timeout=0.5)

    service_element_data = query.service_element_data
    for element in service_element_data:
        service = (element.board,
                   element.cpu,
                   element.objectType,
                   element.messageId,
                   int(element.availableService)
                   )
        services_for_chip.append(service)

    # Add services for FSMr4 ARM cores
    system_type = DSP_RESOURCES.get_system_type_for_board(board)
    if system_type == SYSTEM_TYPE_KEPLER:
        arm_cpu = chip + CPUA
        query = BrowserServicesQuery(
            BrowserServicesReq(board, arm_cpu), BrowserServicesResp()
        )
        qm = BasicQueryManager(query, connection)
        qm.send_request_and_wait_for_response(timeout=1)

        service_element_data = query.service_element_data
        for element in service_element_data:
            service = (element.board,
                       element.cpu,
                       element.objectType,
                       element.messageId,
                       int(element.availableService)
                       )
            services_for_chip.append(service)

    return services_for_chip


class ServiceInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def get_services_for_chip(self, board, chip, humanize=False):
        # type: (int, int, bool) -> List[Tuple[int, int, int]]

        services_for_chip = _get_services_for_chip_and_cache_results(board, chip, self.connection)

        if humanize:
            services_for_chip_description = []
            for board, cpu, object_type, message_id, available_service in services_for_chip:
                board = '0x{:x}'.format(board)
                cpu = '0x{:x}'.format(cpu)
                object_type = get_browser_object_name(object_type)
                message_id = '{}(0x{:X})'.format(get_message_name(message_id), message_id)
                available_service = '{}({})'.format(get_browser_object_name(available_service), available_service)
                services_for_chip_description.append(
                    (board, cpu, object_type, message_id, available_service)
                )
            return services_for_chip_description

        return services_for_chip

    def get_services(self, board, cpu, humanize=False):
        # type: (int, int, bool) -> List[Union[int, str]]
        chip = ((cpu >> FOUR_BITS) << FOUR_BITS)
        services_for_chip = self.get_services_for_chip(board, chip, humanize)

        services_for_cpu = []
        for _board, _cpu, object_type, message_id, available_service in services_for_chip:
            board_as_int, cpu_as_int = intlify(_board, _cpu)
            if board_as_int == board and cpu_as_int == cpu:
                services_for_cpu.append((_board, _cpu, object_type, message_id, available_service))

        return services_for_cpu

    def get_services_for_board(self, board, humanize=False):
        # type: (int, bool) -> List[Tuple[..., Any]]
        services_for_board = []
        for chip in DSP_RESOURCES.get_chip_ids_for_board(board):
            services_for_chip = self.get_services_for_chip(board, chip, humanize)
            services_for_board.extend(services_for_chip)
        return services_for_board

    def get_board_cpu_pairs_with_given_service_or_message(self, service_or_message_id, humanize=False):  # noqa: C901
        # type: (int, bool) -> List[Tuple[int, int]]
        """
        Helper function
        """
        board_and_cpu_ids = set()
        available_boards = (DSP_RESOURCES.available_board_ids
                            or self.get_available_boards(as_hex=False))
        for board in available_boards:
            services_for_board = self.get_services_for_board(board)
            for _board, _cpu, object_type, message_id, available_service in services_for_board:
                if service_or_message_id in (message_id, available_service):
                    if humanize:
                        _board, _cpu = map(hex, (_board, _cpu))
                    board_and_cpu_ids.add((_board, _cpu))

        candidate_board_and_cpu_ids = sorted(list(board_and_cpu_ids))
        service_or_message_name = get_browser_object_name(service_or_message_id)
        if service_or_message_name == 'Unknown':
            service_or_message_name = get_message_name(service_or_message_id)

        if humanize:
            board_cpu_list_for_log = sorted(
                ['{}{}'.format(board, cpu[2:]) for board, cpu in candidate_board_and_cpu_ids]
            )
        else:
            board_cpu_list_for_log = sorted(
                ['0x{:x}{:x}'.format(board, cpu) for board, cpu in candidate_board_and_cpu_ids]
            )
        LOGGER.debug('Service {} ({}) available on {}'.format(
            service_or_message_name, service_or_message_id, board_cpu_list_for_log
        ))

        return candidate_board_and_cpu_ids

    def get_available_boards(self, as_hex=True):
        # type: (bool) -> List[Union[int, str]]
        available_boards = []

        for board in DSP_RESOURCES.board_ids:
            chip_ids = DSP_RESOURCES.get_chip_ids_for_board(board)
            for chip in [chip_ids[0], chip_ids[-1]]:
                services = self.get_services_for_chip(board, chip)
                if services:
                    available_boards.append(board)
                    break

        # update global set
        for board in available_boards:
            DSP_RESOURCES.available_board_ids.add(board)

        if as_hex:
            available_boards = ['0x{:x}'.format(board) for board in available_boards]

        return available_boards
